/**
 * Embedded Base64 Assets for Worth It Course (WIC)
 * Ensures 100% offline & instantaneous zero-CORS rendering for HD Invoice export, ID Card, & Signatures.
 */

export const WIC_BASE64_ASSETS = {
  LOGO: "data:image/png;base64,",
  TTD_DIREKTUR: "data:image/png;base64,",
  TTD_CFO: "data:image/png;base64,",
  STEMPEL: "data:image/png;base64,"
};

export function getSafeWicAsset(
  customUrl: string | undefined | null,
  assetKey: "LOGO" | "TTD_CFO" | "TTD_DIREKTUR" | "STEMPEL"
): string {
  if (customUrl && typeof customUrl === "string") {
    // If it is already a base64 Data URL, safe to use
    if (customUrl.startsWith("data:image/")) {
      return customUrl;
    }
    // Filter out known broken/CORS-blocked external domains
    if (
      !customUrl.includes("iili.io") &&
      !customUrl.includes("blogger.googleusercontent.com") &&
      !customUrl.includes("BQplBTP") &&
      !customUrl.includes("BQqGiLN") &&
      !customUrl.includes("BQqM53F") &&
      (customUrl.startsWith("http://") || customUrl.startsWith("https://") || customUrl.startsWith("/"))
    ) {
      return customUrl;
    }
  }
  return WIC_BASE64_ASSETS[assetKey];
}
